var goals_view_default = ".dreamglows-goals-view {\r\n  height: calc(100vh - 40px - 40px); /* 40px pour les marges Obsidian + 40px pour le padding total (20px * 2) */\r\n  display: flex;\r\n  flex-direction: column;\r\n  padding: 20px;\r\n  box-sizing: border-box;\r\n}\r\n\r\n.dreamglows-content {\r\n  display: flex;\r\n  position: relative;\r\n  flex: 1;\r\n  min-height: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-goals-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 20px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.dreamglows-timeline-container {\r\n  height: 100%;\r\n  overflow: hidden;\r\n  flex-shrink: 0;\r\n  min-height: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.dreamglows-task-container {\r\n  height: 100%;\r\n  display: flex;\r\n  flex: 1;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n/* Styles pour le conteneur de la liste des tâches */\r\n.dreamglows-task-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  width: 100%;\r\n  height: 100%;\r\n  overflow: hidden;\r\n  min-height: 0; /* Important pour que le scroll fonctionne correctement */\r\n}\r\n\r\n.dreamglows-task-list-header,\r\n.dreamglows-task-stats,\r\n.dreamglows-task-search,\r\n.dreamglows-task-filters {\r\n  flex-shrink: 0;\r\n  margin-bottom: 0.5rem; /* Réduit l'espacement */\r\n}\r\n\r\n.dreamglows-tasks-container {\r\n  flex: 1;\r\n  overflow-y: auto;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.5rem;\r\n  padding: 0.5rem; /* Réduit le padding */\r\n  background: var(--background-primary);\r\n  border: 1px dashed var(--background-modifier-border);\r\n  border-radius: 4px;\r\n  transition: background-color 0.2s ease;\r\n  min-height: 0; /* Important pour que le scroll fonctionne correctement */\r\n}\r\n\r\n.dreamglows-tasks-container:hover {\r\n  background: var(--background-primary-alt);\r\n  border-color: var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-tasks-container:empty::after {\r\n  content: \"Double-cliquez pour ajouter une tâche\";\r\n  display: block;\r\n  text-align: center;\r\n  color: var(--text-muted);\r\n  padding: 2rem;\r\n  font-style: italic;\r\n}\r\n\r\n.dreamglows-resize-handle {\r\n  width: 6px;\r\n  background: transparent;\r\n  cursor: col-resize;\r\n  transition: background-color 0.2s ease;\r\n  position: relative;\r\n}\r\n\r\n.dreamglows-resize-handle:hover {\r\n  background: var(--interactive-accent);\r\n  opacity: 0.2;\r\n}\r\n\r\n.dreamglows-resize-handle::after {\r\n  content: '⋮';\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  transform: translate(-50%, -50%);\r\n  color: var(--text-muted);\r\n  font-size: 16px;\r\n  line-height: 1;\r\n  opacity: 0;\r\n  transition: opacity 0.2s ease;\r\n}\r\n\r\n.dreamglows-resize-handle:hover::after {\r\n  opacity: 1;\r\n  color: var(--text-on-accent);\r\n}\r\n\r\n.dreamglows-timeline-item {\r\n  padding: 8px;\r\n  background: var(--background-primary);\r\n  border-radius: 4px;\r\n  box-shadow: var(--shadow-s);\r\n  min-width: 200px;\r\n}\r\n\r\n.dreamglows-timeline-item-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 8px;\r\n}\r\n\r\n.dreamglows-timeline-item-status,\r\n.dreamglows-timeline-item-priority {\r\n  padding: 2px 6px;\r\n  border-radius: 4px;\r\n  font-size: 0.8em;\r\n  font-weight: 500;\r\n}\r\n\r\n/* Styles pour les statuts */\r\n.dreamglows-timeline-item-status {\r\n  padding: 2px 8px;\r\n  border-radius: 12px;\r\n}\r\n\r\n.dreamglows-status-todo {\r\n  background: var(--background-modifier-error);\r\n  color: var(--text-error);\r\n}\r\n\r\n.dreamglows-status-in-progress {\r\n  background: var(--background-modifier-warning);\r\n  color: var(--text-warning);\r\n}\r\n\r\n.dreamglows-status-done {\r\n  background: var(--background-modifier-success);\r\n  color: var(--text-success);\r\n}\r\n\r\n/* Styles pour les priorités */\r\n.dreamglows-timeline-item-priority {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n}\r\n\r\n.dreamglows-priority-high {\r\n  color: var(--text-error);\r\n}\r\n\r\n.dreamglows-priority-medium {\r\n  color: var(--text-warning);\r\n}\r\n\r\n.dreamglows-priority-low {\r\n  color: var(--text-success);\r\n}\r\n\r\n/* Styles pour la barre de progression */\r\n.dreamglows-timeline-item-progress-container {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  margin-top: 8px;\r\n}\r\n\r\n.dreamglows-timeline-item-progress {\r\n  flex: 1;\r\n  height: 6px;\r\n  background: var(--background-modifier-border);\r\n  border-radius: 3px;\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-progress-bar {\r\n  height: 100%;\r\n  background: var(--text-accent);\r\n  border-radius: 3px;\r\n  transition: width 0.3s ease;\r\n}\r\n\r\n.dreamglows-progress-text {\r\n  font-size: 0.8em;\r\n  color: var(--text-muted);\r\n  min-width: 40px;\r\n  text-align: right;\r\n}\r\n\r\n/* Styles pour les tags */\r\n.dreamglows-timeline-item-tags {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 4px;\r\n  margin-top: 8px;\r\n}\r\n\r\n.dreamglows-tag {\r\n  font-size: 0.8em;\r\n  color: var(--text-accent);\r\n  background: var(--background-modifier-hover);\r\n  padding: 2px 6px;\r\n  border-radius: 4px;\r\n}\r\n\r\n/* Animation au survol */\r\n.dreamglows-timeline-item:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: var(--shadow-m);\r\n}\r\n\r\n.dreamglows-timeline-item:hover .dreamglows-progress-bar {\r\n  background: var(--interactive-accent);\r\n}\r\n\r\n/* Styles pour les groupes et axes de temps */\r\n.vis-label {\r\n  font-weight: 600;\r\n  color: var(--text-normal);\r\n  padding: 8px 12px;\r\n  background: var(--background-primary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: 4px;\r\n  box-shadow: var(--shadow-s);\r\n}\r\n\r\n.vis-labelset .vis-label {\r\n  font-size: 1.2em;\r\n  font-weight: 700;\r\n  color: var(--text-accent);\r\n  background: var(--background-secondary);\r\n  border-left: 3px solid var(--text-accent);\r\n  margin: 4px 8px;\r\n}\r\n\r\n.vis-labelset .vis-label:hover {\r\n  background: var(--background-modifier-hover);\r\n}\r\n\r\n.vis-time-axis .vis-text {\r\n  color: var(--text-normal);\r\n  font-weight: 500;\r\n  font-size: 0.9em;\r\n  padding: 4px 8px;\r\n  background: var(--background-primary);\r\n  border-radius: 4px;\r\n  box-shadow: var(--shadow-s);\r\n}\r\n\r\n.vis-time-axis .vis-grid.vis-major {\r\n  border-color: var(--background-modifier-border);\r\n}\r\n\r\n.vis-time-axis .vis-grid.vis-minor {\r\n  border-color: var(--background-modifier-border-hover);\r\n}\r\n\r\n.vis-panel.vis-center {\r\n  border-color: var(--background-modifier-border);\r\n}\r\n\r\n.vis-panel.vis-left {\r\n  border-color: var(--background-modifier-border);\r\n}\r\n\r\n/* Amélioration du contraste pour les groupes */\r\n.vis-group {\r\n  border-color: var(--background-modifier-border);\r\n  background: var(--background-primary);\r\n}\r\n\r\n.vis-group:nth-child(odd) {\r\n  background: var(--background-secondary);\r\n}\r\n\r\n.vis-group:hover {\r\n  background: var(--background-modifier-hover);\r\n}\r\n\r\n/* Styles pour les contrôles de zoom */\r\n.dreamglows-timeline-controls {\r\n  position: absolute;\r\n  bottom: 16px;\r\n  right: 16px;\r\n  display: flex;\r\n  gap: 8px;\r\n  z-index: 1;\r\n}\r\n\r\n.dreamglows-timeline-control {\r\n  padding: 8px;\r\n  background: var(--background-secondary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: 4px;\r\n  color: var(--text-normal);\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n.dreamglows-timeline-control:hover {\r\n  background: var(--background-modifier-hover);\r\n  transform: scale(1.1);\r\n}\r\n\r\n/* Amélioration des items de la timeline */\r\n.vis-item {\r\n  border-radius: 4px;\r\n  border-width: 1px;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n.vis-item:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: var(--shadow-s);\r\n}\r\n\r\n.vis-item.vis-selected {\r\n  border-color: var(--text-accent);\r\n  box-shadow: 0 0 0 2px var(--text-accent-hover);\r\n}\r\n\r\n/* Styles pour le drag & drop */\r\n.vis-item.vis-drag-center {\r\n  background: var(--background-modifier-success);\r\n}\r\n\r\n.vis-item.vis-range.vis-drag-center {\r\n  border-color: var(--text-accent);\r\n}\r\n\r\n/* Style du bouton d'ajout */\r\n.dreamglows-add-goal-btn {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 8px 16px;\r\n  border-radius: 4px;\r\n  background: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n  border: none;\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n.dreamglows-add-goal-btn:hover {\r\n  background: var(--interactive-accent-hover);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n.dreamglows-add-goal-btn i {\r\n  font-size: 0.9em;\r\n}\r\n\r\n/* Styles pour les tooltips */\r\n.dreamglows-timeline-tooltip {\r\n  padding: 8px;\r\n  max-width: 300px;\r\n}\r\n\r\n.dreamglows-timeline-tooltip h3 {\r\n  margin: 0 0 8px 0;\r\n  font-size: 1em;\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-timeline-tooltip p {\r\n  margin: 0 0 8px 0;\r\n  font-size: 0.9em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-tooltip-meta {\r\n  display: flex;\r\n  gap: 8px;\r\n  font-size: 0.8em;\r\n  color: var(--text-muted);\r\n  margin-bottom: 4px;\r\n}\r\n\r\n.dreamglows-tooltip-tags {\r\n  font-size: 0.8em;\r\n  color: var(--text-accent);\r\n} \r\n\r\n.dreamglows-timeline-item {\r\n  padding: 8px;\r\n  border-radius: 4px;\r\n  background: var(--background-primary);\r\n}\r\n\r\n.dreamglows-timeline-item-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 4px;\r\n}\r\n\r\n.dreamglows-timeline-item-status {\r\n  font-size: 0.9em;\r\n  padding: 2px 6px;\r\n  border-radius: 3px;\r\n}\r\n\r\n.dreamglows-status-todo .dreamglows-timeline-item {\r\n  background: var(--background-primary);\r\n  border: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-status-in-progress .dreamglows-timeline-item {\r\n  background: var(--background-primary-alt);\r\n  border: 1px solid var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-status-done .dreamglows-timeline-item {\r\n  background: var(--background-success);\r\n  border: 1px solid var(--text-success);\r\n}\r\n\r\n.dreamglows-priority-high .dreamglows-timeline-item {\r\n  border-left: 4px solid var(--text-error);\r\n}\r\n\r\n.dreamglows-priority-medium .dreamglows-timeline-item {\r\n  border-left: 4px solid var(--text-warning);\r\n}\r\n\r\n.dreamglows-priority-low .dreamglows-timeline-item {\r\n  border-left: 4px solid var(--text-success);\r\n}\r\n\r\n.dreamglows-timeline-item-title {\r\n  font-weight: 500;\r\n  margin-bottom: 4px;\r\n}\r\n\r\n.dreamglows-progress-container {\r\n  flex: 1;\r\n  height: 6px;\r\n  background: var(--background-modifier-border);\r\n  border-radius: 3px;\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-progress-bar {\r\n  height: 100%;\r\n  transition: width 0.3s ease;\r\n}\r\n\r\n.dreamglows-progress-text {\r\n  margin-left: 8px;\r\n  font-size: 0.9em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-timeline-item-tags {\r\n  margin-top: 4px;\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 4px;\r\n}\r\n\r\n.dreamglows-tag {\r\n  font-size: 0.8em;\r\n  padding: 2px 6px;\r\n  background: var(--background-modifier-hover);\r\n  border-radius: 3px;\r\n  color: var(--text-muted);\r\n}";
