var time_nav_default = ".dreamglows-time-navigation {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 1rem;\r\n    white-space: nowrap;\r\n}\r\n\r\n.dreamglows-nav-controls {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 0.5rem;\r\n}\r\n\r\n.dreamglows-nav-btn {\r\n    background: none;\r\n    border: none;\r\n    cursor: pointer;\r\n    padding: 0.5rem;\r\n    border-radius: 4px;\r\n    transition: background-color 0.2s;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 32px;\r\n    height: 32px;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-nav-btn:hover {\r\n    background-color: var(--background-modifier-hover);\r\n    color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-time-navigation h2 {\r\n    margin: 0;\r\n    font-size: 1rem;\r\n    font-weight: 600;\r\n    min-width: 200px;\r\n    text-align: center;\r\n    color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-today-btn {\r\n    padding: 0.25rem 0.75rem;\r\n    border-radius: 4px;\r\n    background-color: var(--interactive-accent);\r\n    color: var(--text-on-accent);\r\n    border: none;\r\n    cursor: pointer;\r\n    transition: background-color 0.2s;\r\n    font-size: 0.9rem;\r\n}\r\n\r\n.dreamglows-today-btn:hover {\r\n    background-color: var(--interactive-accent-hover);\r\n}\r\n\r\n.dreamglows-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: 0.5rem;\r\n    border-bottom: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-view-switch {\r\n    display: flex;\r\n    gap: 0.5rem;\r\n}";
