var profile_view_default = ".dreamglows-profile-view {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-md);\r\n}\r\n\r\n.dreamglows-profile-summary {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-profile-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\r\n  gap: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-profile-card {\r\n  background: var(--background-secondary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  padding: var(--dreamglows-spacing-md);\r\n}\r\n\r\n.dreamglows-profile-card h3 {\r\n  margin: 0;\r\n  font-size: 0.9rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-profile-value {\r\n  font-size: 1.3rem;\r\n  font-weight: 600;\r\n  margin-top: var(--dreamglows-spacing-xs);\r\n}\r\n\r\n.dreamglows-profile-sub {\r\n  margin-top: 2px;\r\n  font-size: 0.85rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-profile-progress-wrap {\r\n  margin-top: var(--dreamglows-spacing-sm);\r\n  width: 100%;\r\n  height: 0.4rem;\r\n  border-radius: 999px;\r\n  background: var(--background-modifier-hover);\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-profile-progress {\r\n  height: 100%;\r\n  width: 0;\r\n  background: var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-profile-section {\r\n  background: var(--background-primary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  padding: var(--dreamglows-spacing-md);\r\n}\r\n\r\n.dreamglows-profile-section h3 {\r\n  margin: 0 0 var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-profile-breakdown,\r\n.dreamglows-profile-rewards {\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-xs);\r\n}\r\n\r\n.dreamglows-profile-breakdown li {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  font-size: 0.9rem;\r\n}\r\n\r\n.dreamglows-profile-rewards li {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  gap: var(--dreamglows-spacing-sm);\r\n  font-size: 0.85rem;\r\n}\r\n\r\n.dreamglows-profile-reward-message {\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-profile-reward-date,\r\n.dreamglows-profile-empty {\r\n  color: var(--text-muted);\r\n  white-space: nowrap;\r\n}\r\n";
