function registerStyles(viewType) {
	const styleEl = document.createElement("style");
	styleEl.id = "dreamglows-styles";
	styleEl.textContent = `
        /* Styles de base */
        ${planning_view_default}
        ${goals_view_default}
        ${task_list_default}
        ${day_view_default}
        ${time_nav_default}
        ${category_modal_content_default}
        ${stats_view_default}
        ${profile_view_default}
        ${main_view_default}

        /* Styles spécifiques à la vue */
        ${week_view_default}
        ${viewType === "list" ? list_view_default : ""}
        ${viewType === "daily" ? daily_view_default : ""}
        ${viewType === "day" ? day_view_default : ""}
    `;
	document.head.appendChild(styleEl);
}
function unregisterStyles() {
	const styleEl = document.getElementById("dreamglows-styles");
	if (styleEl) styleEl.remove();
}
