//#region src/services/ValidationService.ts
var ValidationService = class {
	constructor(dateService, settings) {
		this.dateService = dateService;
		this.settings = settings;
	}
	/**
	* Valide un objectif
	*/
	validateGoal(goal) {
		try {
			const validatedGoal = GoalSchema.parse(goal);
			this.validateDates(validatedGoal.startDate, validatedGoal.dueDate);
			if (validatedGoal.metrics) MetricsSchema.parse(validatedGoal.metrics);
			return validatedGoal;
		} catch (error) {
			if (error instanceof ZodError) throw new ValidationError("Validation du goal échouée", error.errors.map((e) => e.message).join(", "));
			throw error;
		}
	}
	/**
	* Valide une tâche
	*/
	validateTask(task) {
		try {
			const validatedTask = TaskSchema.parse(task);
			this.validateDates(validatedTask.startDate, validatedTask.dueDate);
			this.validateDates(validatedTask.createdAt, validatedTask.updatedAt);
			return validatedTask;
		} catch (error) {
			if (error instanceof ZodError) throw new ValidationError("Validation de la tâche échouée", error.errors.map((e) => e.message).join(", "));
			throw error;
		}
	}
	/**
	* Valide une liste d'objectifs
	*/
	validateGoalsList(goals) {
		try {
			const validatedGoals = arrayType(GoalSchema).parse(goals);
			const goalIds = new Set(validatedGoals.map((g) => g.id));
			for (const goal of validatedGoals) for (const subGoalId of goal.subGoalIds) if (!goalIds.has(subGoalId)) throw new ConsistencyError("Référence à un sous-objectif inexistant", subGoalId);
			return validatedGoals;
		} catch (error) {
			if (error instanceof ZodError) throw new ValidationError("Validation de la liste des goals échouée", error.errors.map((e) => e.message).join(", "));
			throw error;
		}
	}
	/**
	* Valide une liste de tâches
	*/
	validateTasksList(tasks) {
		try {
			const validatedTasks = arrayType(TaskSchema).parse(tasks);
			for (const task of validatedTasks) this.validateDates(task.createdAt, task.updatedAt);
			return validatedTasks;
		} catch (error) {
			if (error instanceof ZodError) throw new ValidationError("Validation de la liste des tâches échouée", error.errors.map((e) => e.message).join(", "));
			throw error;
		}
	}
	/**
	* Valide la cohérence entre une tâche et son objectif
	*/
	validateTaskGoalConsistency(task, goal) {
		if (!task.goalId || task.goalId !== goal.id) throw new ConsistencyError("La tâche n'est pas liée à l'objectif", task.id);
		if (!this.dateService.isInRange(task.startDate, goal.startDate, goal.dueDate)) throw new ConsistencyError("La date de début de la tâche est en dehors de la période de l'objectif", task.id);
		if (!this.dateService.isInRange(task.dueDate, goal.startDate, goal.dueDate)) throw new ConsistencyError("La date de fin de la tâche est en dehors de la période de l'objectif", task.id);
	}
	/**
	* Valide le store de données complet
	*/
	validateDataStore(data) {
		try {
			const validatedStore = DataStoreSchema.parse(data);
			const goalIds = new Set(validatedStore.goals.map((g) => g.id));
			for (const task of validatedStore.tasks) if (task.goalId && !goalIds.has(task.goalId)) throw new ConsistencyError("Référence à un objectif inexistant", task.goalId);
			const taskIds = new Set(validatedStore.tasks.map((t) => t.id));
			for (const goal of validatedStore.goals) for (const taskId of goal.tasks) if (!taskIds.has(taskId)) throw new ConsistencyError("Référence à une tâche inexistante", taskId);
			return validatedStore;
		} catch (error) {
			if (error instanceof ZodError) throw new ValidationError("Validation du store échouée", error.errors.map((e) => e.message).join(", "));
			throw error;
		}
	}
	/**
	* Valide les dates
	*/
	validateDates(startDate, endDate) {
		if (!this.dateService.validateDate(startDate)) throw new ValidationError("Date invalide", `Format de date invalide : ${startDate}`);
		if (!this.dateService.validateDate(endDate)) throw new ValidationError("Date invalide", `Format de date invalide : ${endDate}`);
		if (this.dateService.compare(startDate, endDate) > 0) throw new ValidationError("Dates incohérentes", "La date de début doit être antérieure ou égale à la date de fin");
	}
	validateNoteContent(content) {
		const requiredSections = getDefaultTemplate(this.settings.monthLanguage).split("\n").filter((line) => line.startsWith("##")).map((line) => line.trim());
		for (const section of requiredSections) if (!content.includes(section)) throw new ValidationError("Structure de note invalide", `La section "${section}" est manquante`);
		const titleLines = content.split("\n").filter((line) => line.startsWith("#"));
		const forbiddenChars = /[<>:"|?*]/;
		for (const title of titleLines) if (forbiddenChars.test(title)) throw new ValidationError("Caractères invalides dans le titre", `Le titre "${title}" contient des caractères non autorisés`);
		const tagRegex = /#[a-zA-Z0-9-]+/g;
		const tags = content.match(/#[^\s#]+/g) || [];
		for (const tag of tags) if (!tagRegex.test(tag)) throw new ValidationError("Format de tag invalide", `Le tag "${tag}" ne respecte pas le format #tag-name`);
	}
	validateLatexAndCode(content) {
		if (content.includes("$")) throw new ValidationError("LaTeX non supporté", "Le LaTeX inline ($...$) n'est pas supporté pour éviter les conflits de parsing");
		if (content.includes("```")) throw new ValidationError("Blocs de code non supportés", "Les blocs de code ne sont pas supportés pour éviter les conflits de parsing");
	}
};
