//#region src/constants/emojis.ts
var STATUS_EMOJI = {
	"todo": "🔵",
	"in-progress": "🟡",
	"done": "🟢"
};
var EMOJI_STATUS = {
	"🔵": "todo",
	"🟡": "in-progress",
	"🟢": "done"
};
//#endregion
//#region src/constants/formats.ts
var DELIMITERS = {
	SECTION: "##",
	SUBSECTION: "###",
	ITEM: "|",
	TAG: "#",
	TASK_REF: "#task-",
	GOAL_REF: "#goal-"
};
var SECTIONS = {
	FR: {
		GOALS: "🎯 Objectifs atteints",
		DIARY: "📝 Journal",
		REVIEW: "📊 Bilan de la journée"
	},
	EN: {
		GOALS: "🎯 Goals Achieved",
		DIARY: "📝 Diary",
		REVIEW: "📊 Daily Review"
	}
};
var MIN_FIELDS = {
	GOAL: 10,
	TASK: 8
};
var FIELD_INDEX = {
	TITLE_AND_STATUS: 0,
	ID: 1,
	CATEGORY_OR_GOAL_ID: 2,
	PRIORITY: 3,
	START_DATE: 4,
	DUE_DATE: 5,
	PROGRESS_OR_DESCRIPTION: 6,
	DESCRIPTION_OR_NOTES: 7,
	METRICS_OR_TAGS: 8,
	TASKS: 9,
	TAGS: 10
};
